  const root = makeRepo({
    base: { 'src/app.mjs': '// says what the next line says\ncall();\n' },
    changed: { 'src/app.mjs': 'call();\n' },
    commitMsg: RUN,
  });
  try {
    assert.deepEqual(runScope(root), []);
  } finally { cleanup(root); }
});

