p='packs/tidy-repo/skills/improve-comments/checks.mjs'
s=open(p).read()
s=s.replace("""//   - ANY change under `.claudinite/`, comment-only or not. The mount is vendored:
//     the next converge replaces `shared/` whole, so a comment improved there is
//     gone by morning, and the lifecycle rules forbid editing it at all. The task's
//     precondition keeps those paths out of a round's scope; this is what holds
//     when a run reaches for one anyway.""","""//   - ANY change under `.claudinite/`, comment-only or not. The mount is not the
//     repo's own source: `shared/` is vendored and the next converge replaces it
//     whole (that half is already invisible to every check — repo-context drops
//     the shared prefix), and `.claudinite/local/` is what the growth tasks write.
//     The task's precondition keeps the mount out of a round's scope; this is what
//     holds when a run reaches for one anyway.""")
open(p,'w').write(s)

p='packs/tidy-repo/test/skills/improve-comments/checks.test.mjs'
s=open(p).read()
s=s.replace("""// `.claudinite/` is the vendored mount and the local packs: the converge replaces
// `shared/` wholesale, so a comment edit there is lost on the next run and the
// lifecycle rules forbid it outright. Both halves of the exclusion are asserted —
// the scope a round is handed, and the gate that reds the write.
test('a change under .claudinite/ is out of this pass\\'s surface, comment-only or not', () => {
  const root = makeRepo({
    base: { '.claudinite/shared/packs/basics/pack.mjs': '// vendored note\\nexport default {};\\n' },
    changed: { '.claudinite/shared/packs/basics/pack.mjs': '// a better vendored note\\nexport default {};\\n' },
    commitMsg: RUN,
  });
  try {
    const findings = runScope(root);
    assert.deepEqual(files(findings), ['.claudinite/shared/packs/basics/pack.mjs']);
    assert.match(findings[0].what, /\\.claudinite\\//);
  } finally { cleanup(root); }
});""","""// `.claudinite/` is the mount, not the repo's own source. The vendored `shared/`
// half is already invisible to every check, so what the gate has to carry is
// `.claudinite/local/`, which a run can reach and edit. Both halves of the
// exclusion are asserted — the scope a round is handed, and the gate on the write.
test('a comment-only edit inside .claudinite/ is still outside this pass\\'s surface', () => {
  const root = makeRepo({
    base: { '.claudinite/local/packs/x/hook.mjs': '// the old note\\nrun();\\n' },
    changed: { '.claudinite/local/packs/x/hook.mjs': '// a better note\\nrun();\\n' },
    commitMsg: RUN,
  });
  try {
    const findings = runScope(root);
    assert.deepEqual(files(findings), ['.claudinite/local/packs/x/hook.mjs']);
    assert.match(findings[0].what, /\\.claudinite\\//);
    assert.match(findings[0].fix, /revert \\.claudinite\\/local\\/packs\\/x\\/hook\\.mjs/);
  } finally { cleanup(root); }
});""")
open(p,'w').write(s)
